def parse_nvda(xml_text):
    tables = re.split(r'</?infoTable>', xml_text)
    results = []
    for t in tables:
        if 'NVIDIA CORPORATION' not in t:
            continue
        sh = re.search(r'<sshPrnamt>(\d+)', t)
        val = re.search(r'<value>(\d+)', t)
        sol = re.search(r'<Sole>(\d+)', t)
        shd = re.search(r'<Shared>(\d+)', t)
        results.append({
            'shares': int(sh.group(1)) if sh else 0,
            'value': int(val.group(1)) if val else 0,
            'sole': int(sol.group(1)) if sol else 0,
            'shared': int(shd.group(1)) if shd else 0,
        })
    return results

def fetch_filing_xml(acc_no, master_cik):
    acc_clean = acc_no.replace('-', '')
    base = master_cik.lstrip('0')
    idx_url = f'https://www.sec.gov/Archives/edgar/data/{base}/{acc_clean}/'
    try:
        resp = requests.get(idx_url, headers=headers, timeout=30)
        if resp.status_code != 200:
            return None
        soup = BeautifulSoup(resp.text, 'html.parser')
        xml_urls = []
        for a in soup.find_all('a'):
            href = a.get('href', '')
            if href and href.endswith('.xml'):
                if href.startswith('/'):
                    xml_urls.append('https://www.sec.gov' + href)
                else:
                    xml_urls.append(idx_url + href)
        for xu in xml_urls:
            r = requests.get(xu, headers=headers, timeout=60)
            if r.status_code == 200 and b'informationTable' in r.content:
                return r.text
    except:
        pass
    return None

# Fetch all data
